CREATE SET TABLE MDP01_META.META_LAYER ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      layer_id INTEGER NOT NULL,      layer_name VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      layer_code VARCHAR(20) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      layer_sequence INTEGER NOT NULL,      layer_beschreibung VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      modellierungsansatz VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      ersterfassungsdatum TIMESTAMP(6) NOT NULL,      aenderungsdatum TIMESTAMP(6) NOT NULL,      erfasst_durch VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      geaendert_durch VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL)PRIMARY INDEX ( layer_id )UNIQUE INDEX ( layer_name )UNIQUE INDEX ( layer_code );